// Heuristics only; a photograph's content cannot be certified by these measures.
export function scanMetrics({data,width,height,channels=4,originalWidth=width,originalHeight=height}){if(!data||width<3||height<3)throw new Error('Bild zu klein.');let sum=0,sum2=0,lap=0,lap2=0,edges=0,saturated=0,highlight=0;const gray=(x,y)=>{const i=(y*width+x)*channels;return channels<3?data[i]:.2126*data[i]+.7152*data[i+1]+.0722*data[i+2];};for(let y=1;y<height-1;y++)for(let x=1;x<width-1;x++){const v=gray(x,y),l=4*v-gray(x-1,y)-gray(x+1,y)-gray(x,y-1)-gray(x,y+1);sum+=v;sum2+=v*v;lap+=l;lap2+=l*l;if(v>250)highlight++;if(v<5||v>250)saturated++;if((x<width*.025||x>width*.975||y<height*.025||y>height*.975)&&v<80)edges++;}const n=(width-2)*(height-2),variance=lap2/n-(lap/n)**2,contrast=Math.sqrt(Math.max(0,sum2/n-(sum/n)**2)),warnings=[];if(Math.min(originalWidth,originalHeight)<900)warnings.push('Geringe Auflösung: kleine Schrift könnte unleserlich sein.');if(variance<35&&contrast<35)warnings.push('Mögliche Unschärfe oder sehr kontrastarme Aufnahme.');if(sum/n<65)warnings.push('Sehr dunkle Aufnahme.');if(highlight/n>.88&&contrast<25)warnings.push('Sehr helle Aufnahme: mögliche Überbelichtung; Spiegelungen visuell prüfen.');if(edges/n>.006)warnings.push('Dunkle Inhalte nahe am Rand: auf abgeschnittene Angaben prüfen.');return {width:originalWidth,height:originalHeight,sharpness:Math.round(variance),contrast:Math.round(contrast),brightness:Math.round(sum/n),warnings,note:'Heuristische Hinweise, keine verlässliche Erkennung aller Spiegelungen, Unschärfen oder abgeschnittenen Inhalte.'};}
